CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY, name text NOT NULL, default_timezone text NOT NULL DEFAULT 'UTC', created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS organization_settings (id uuid PRIMARY KEY, organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id), no_show_timeout_minutes int NOT NULL DEFAULT 15, qr_token_ttl_seconds int NOT NULL DEFAULT 20, allow_self_signup boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, display_name text NOT NULL, auth_provider text NOT NULL DEFAULT 'Password', role text NOT NULL, password_hash text, is_active boolean NOT NULL DEFAULT true, invited_at timestamptz, created_at timestamptz NOT NULL, UNIQUE(organization_id,email));
ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_provider text NOT NULL DEFAULT 'Password';
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, building text NOT NULL DEFAULT '', floor text NOT NULL DEFAULT '', capacity int NOT NULL, equipment_tags text[] NOT NULL DEFAULT '{}', photo_urls text[] NOT NULL DEFAULT '{}', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL);
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS static_check_in_code text;
UPDATE rooms SET static_check_in_code = replace(gen_random_uuid()::text, '-', '') WHERE static_check_in_code IS NULL OR static_check_in_code = '';
ALTER TABLE rooms ALTER COLUMN static_check_in_code SET DEFAULT replace(gen_random_uuid()::text, '-', '');
ALTER TABLE rooms ALTER COLUMN static_check_in_code SET NOT NULL;
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS requires_approval boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS recurring_series (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), room_id uuid NOT NULL REFERENCES rooms(id), user_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, recurrence_rule text NOT NULL, series_start_date date NOT NULL, series_end_date date NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), room_id uuid NOT NULL REFERENCES rooms(id), user_id uuid NOT NULL REFERENCES users(id), recurring_series_id uuid REFERENCES recurring_series(id), title text NOT NULL, attendee_count int NOT NULL DEFAULT 1, notes text, start_at_utc timestamptz NOT NULL, end_at_utc timestamptz NOT NULL, status text NOT NULL DEFAULT 'Confirmed', created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS attendee_count int NOT NULL DEFAULT 1;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS notes text;
ALTER TABLE bookings DROP CONSTRAINT IF EXISTS no_overlapping_bookings;
ALTER TABLE bookings ADD CONSTRAINT no_overlapping_bookings EXCLUDE USING gist (room_id WITH =, tstzrange(start_at_utc,end_at_utc) WITH &&) WHERE (status NOT IN ('Cancelled','NoShow'));
CREATE TABLE IF NOT EXISTS qr_devices (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), room_id uuid NOT NULL UNIQUE REFERENCES rooms(id), device_identifier text NOT NULL, current_token text NOT NULL, token_expires_at timestamptz NOT NULL, last_seen_at timestamptz);
CREATE TABLE IF NOT EXISTS check_in_events (id uuid PRIMARY KEY, booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), checked_in_at timestamptz, checked_out_at timestamptz, auto_cancelled boolean NOT NULL DEFAULT false, auto_checked_out boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), actor_user_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id uuid NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organization_settings','users','rooms','recurring_series','bookings','qr_devices','audit_logs'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (organization_id = nullif(current_setting(''app.current_org_id'', true), '''')::uuid) WITH CHECK (organization_id = nullif(current_setting(''app.current_org_id'', true), '''')::uuid)',t); END LOOP; END $$;
